schemas.ddl:
CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT, country TEXT);
CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, total REAL, placed_at TEXT, FOREIGN KEY (customer_id) REFERENCES customers(id));
CREATE TABLE order_items (id INTEGER PRIMARY KEY, order_id INTEGER, product_id INTEGER, qty INTEGER, FOREIGN KEY (order_id) REFERENCES orders(id), FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT, price REAL);
CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE suppliers (id INTEGER PRIMARY KEY, name TEXT, country TEXT);
CREATE TABLE warehouses (id INTEGER PRIMARY KEY, city TEXT);
CREATE TABLE inventory (product_id INTEGER, warehouse_id INTEGER, on_hand INTEGER, FOREIGN KEY (product_id) REFERENCES products(id), FOREIGN KEY (warehouse_id) REFERENCES warehouses(id));
CREATE TABLE reviews (product_id INTEGER, customer_id INTEGER, stars INTEGER, FOREIGN KEY (product_id) REFERENCES products(id), FOREIGN KEY (customer_id) REFERENCES customers(id));
CREATE TABLE support_tickets (id INTEGER PRIMARY KEY, customer_id INTEGER, subject TEXT, status TEXT, FOREIGN KEY (customer_id) REFERENCES customers(id));
CREATE TABLE shipments (id INTEGER PRIMARY KEY, order_id INTEGER, carrier TEXT, FOREIGN KEY (order_id) REFERENCES orders(id));
CREATE TABLE payments (id INTEGER PRIMARY KEY, order_id INTEGER, amount REAL, method TEXT, FOREIGN KEY (order_id) REFERENCES orders(id));

CREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT, major TEXT);
CREATE TABLE courses (id INTEGER PRIMARY KEY, title TEXT, credits INTEGER);
CREATE TABLE enrollments (student_id INTEGER, course_id INTEGER, grade REAL, FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (course_id) REFERENCES courses(id));
CREATE TABLE instructors (id INTEGER PRIMARY KEY, name TEXT, dept TEXT);
CREATE TABLE departments (id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE classrooms (id INTEGER PRIMARY KEY, building TEXT, capacity INTEGER);
CREATE TABLE schedules (course_id INTEGER, classroom_id INTEGER, weekday TEXT, FOREIGN KEY (course_id) REFERENCES courses(id), FOREIGN KEY (classroom_id) REFERENCES classrooms(id));

CREATE TABLE patients (id INTEGER PRIMARY KEY, name TEXT, dob TEXT);
CREATE TABLE doctors (id INTEGER PRIMARY KEY, name TEXT, specialty TEXT);
CREATE TABLE appointments (id INTEGER PRIMARY KEY, patient_id INTEGER, doctor_id INTEGER, scheduled_at TEXT, FOREIGN KEY (patient_id) REFERENCES patients(id), FOREIGN KEY (doctor_id) REFERENCES doctors(id));
CREATE TABLE prescriptions (id INTEGER PRIMARY KEY, patient_id INTEGER, drug TEXT, dosage TEXT, FOREIGN KEY (patient_id) REFERENCES patients(id));
CREATE TABLE wards (id INTEGER PRIMARY KEY, name TEXT, capacity INTEGER);
CREATE TABLE diagnoses (patient_id INTEGER, code TEXT, noted_at TEXT, FOREIGN KEY (patient_id) REFERENCES patients(id));

CREATE TABLE accounts (id INTEGER PRIMARY KEY, holder TEXT, balance REAL);
CREATE TABLE transactions (id INTEGER PRIMARY KEY, account_id INTEGER, amount REAL, posted_at TEXT, FOREIGN KEY (account_id) REFERENCES accounts(id));
CREATE TABLE branches (id INTEGER PRIMARY KEY, city TEXT);
CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT, branch_id INTEGER, FOREIGN KEY (branch_id) REFERENCES branches(id));
CREATE TABLE loans (id INTEGER PRIMARY KEY, customer_id INTEGER, principal REAL, rate REAL, FOREIGN KEY (customer_id) REFERENCES customers(id));
CREATE TABLE fraud_flags (transaction_id INTEGER, reason TEXT, FOREIGN KEY (transaction_id) REFERENCES transactions(id));
